def _encode(vals, left, right, root):
    if root == -1:
        return []
    out = []
    q = [root]
    for x in q:
        if x == -1:
            out.append(-1)
        else:
            out.append(vals[x])
            q.append(left[x])
            q.append(right[x])
    while out and out[-1] == -1:
        out.pop()
    return out


def buildTree(inorder, postorder):
    n = len(postorder)
    if n == 0:
        return []
    pos = {v: i for i, v in enumerate(inorder)}
    left = [-1] * n
    right = [-1] * n
    # node id = index in postorder; a task is (postorder start, inorder start, size)
    stack = [(0, 0, n)]
    while stack:
        q, s, size = stack.pop()
        root = q + size - 1
        k = pos[postorder[root]] - s  # nodes in the left subtree
        if k > 0:
            left[root] = q + k - 1
            stack.append((q, s, k))
        if size - 1 - k > 0:
            right[root] = root - 1
            stack.append((q + k, s + k + 1, size - 1 - k))
    return _encode(postorder, left, right, n - 1)
